SELECT count(*) AS n,COALESCE(sum(CASE WHEN length(row_sha)=64 AND row_sha NOT GLOB '*[^0-9a-f]*' THEN 1 ELSE 0 END),0) AS valid_n,length(CAST(COALESCE(group_concat(row_sha,''),'') AS BLOB)) AS concat_bytes,lower(hex(crypto_sha256(CAST('casepath-source-bytes-v1:set:'||COALESCE(group_concat(row_sha,''),'') AS BLOB)))) AS root FROM (SELECT lower(hex(crypto_sha256(CAST('casepath-source-bytes-v1:row:'||(CASE typeof(sha256) WHEN 'text' THEN 't' WHEN 'integer' THEN 'i' WHEN 'blob' THEN 'b' WHEN 'real' THEN 'r' WHEN 'null' THEN 'n' ELSE '?' END)||printf('%016x',length(COALESCE(CAST(sha256 AS BLOB),X'')))||lower(hex(crypto_sha256(COALESCE(CAST(sha256 AS BLOB),X''))))||(CASE typeof(chunk_index) WHEN 'text' THEN 't' WHEN 'integer' THEN 'i' WHEN 'blob' THEN 'b' WHEN 'real' THEN 'r' WHEN 'null' THEN 'n' ELSE '?' END)||printf('%016x',length(COALESCE(CAST(chunk_index AS BLOB),X'')))||lower(hex(crypto_sha256(COALESCE(CAST(chunk_index AS BLOB),X''))))||(CASE typeof(content) WHEN 'text' THEN 't' WHEN 'integer' THEN 'i' WHEN 'blob' THEN 'b' WHEN 'real' THEN 'r' WHEN 'null' THEN 'n' ELSE '?' END)||printf('%016x',length(COALESCE(CAST(content AS BLOB),X'')))||lower(hex(crypto_sha256(COALESCE(CAST(content AS BLOB),X'')))) AS BLOB)))) AS row_sha FROM (SELECT 'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb' AS sha256,CAST('0' AS INTEGER) AS chunk_index,X'' AS content UNION ALL SELECT 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa' AS sha256,CAST('9223372036854775807' AS INTEGER) AS chunk_index,X'cea900' AS content UNION ALL SELECT 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa' AS sha256,CAST('-9223372036854775808' AS INTEGER) AS chunk_index,X'00ff' AS content) WHERE 1 ORDER BY sha256,chunk_index LIMIT ?)